head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFocusMode]<br/>GridView 컴포넌트의 focusMode 속성을 설정합니다.",
    "validation" : [
        "focusMode 속성을 설정합니다.",
        "focusMode 파라미터(필수)에 'cell' 을 설정하면 선택된 Body Cell 영역이 포커스됩니다.",
        "focusMode 파라미터(필수)에 'row' 를 설정하면 선택된 Body Row 영역이 포커스됩니다.",
        "focusMode 파라미터(필수)에 'both' 를 설정하면 선택된 Body Cell 과 Body Row 영역이 모두 포커스됩니다.",
        "focusMode 파라미터(필수)에 이외의 값('none' 포함)이나 현재 focusMode 와 동일한 값을 설정하면 메소드가 실행되지 않습니다.",
        "setFocusMode() 가 실행되면 이전 포커스 상태가 모두 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 기본 focusMode='none' 로 생성 (setFocusMode 는 현재값과 동일하면 미실행이므로,
//    초기값을 'none' 으로 두어 par 로 cell/row/both 중 무엇을 선택해도 첫 변경이 유효하게 동작)
//  - selectedCellColor(red) 와 selectedRowColor(blue) 를 서로 다른 색으로 하드코딩하여
//    cell/row/both 포커스 결과를 배경색으로 구분 가능하게 함
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (cell/row/both 결과를 색으로 구분: Cell=red, Row=blue)
    let properties = {
        focusMode        : "none",
        selectedCellColor: "red",
        selectedRowColor : "blue"
    };
    let cList = $c.gcm.createCList(properties);

    // 셀 클릭 시에도 선택 상태를 출력하도록 oncellclick 바인딩
    let eList = $c.gcm.createEList(["oncellclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="focusMode=none / selectedCellColor=red / selectedRowColor=blue 로 GridView 생성"', '', 'label1');

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (4컬럼 Body 그리드)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setFocusMode 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 재포커스 후 선택 상태(셀/Row 강조)를 focusMode 에 맞춰 출력하는 공통 함수
//  - 포커스 인덱스(getFocusedRowIndex/ColumnIndex) + 실제 셀 배경색(computed style)을 함께 표시
//  - cell : 포커스된 Cell 1개만 selectedCellColor(red) 적용
//  - row  : 포커스된 Row 전체 셀이 selectedRowColor(blue) 적용
//  - both : 포커스 Cell(red, selectedCellColor) + 동일 Row 다른 Cell(blue, selectedRowColor) 둘 다
scwin.printFocusColors = function (rowIndex, colIndex) {
    let mode = target1.options.focusMode;
    let bottom = wf_body_bottom.getObj("scwin");

    let getColor = function (r, c) {
        let td = document.querySelector("td[id*='mf_target1_cell_" + r + "_" + c + "']");
        return td ? window.getComputedStyle(td).backgroundColor : "(cell 없음)";
    };

    // 재포커스 후 실제 포커스 인덱스
    let fRow = target1.getFocusedRowIndex();
    let fCol = target1.getFocusedColumnIndex();
    bottom.setReturnValue("[선택된 셀/Row 상태] focusMode=" + mode + " / 포커스 인덱스 row=" + fRow + ",col=" + fCol);

    if (mode === 'row') {
        // 포커스 Row 전체가 selectedRowColor(blue) 로 강조
        bottom.setReturnValue("[Row 선택 강조] 포커스 Row(" + rowIndex + ") 전체 selectedRowColor 적용 → Cell(" + rowIndex + "," + colIndex + ") 배경색 " + getColor(rowIndex, colIndex) + " / 동일 Row Cell(" + rowIndex + ",0) 배경색 " + getColor(rowIndex, 0));
    } else if (mode === 'both') {
        // 포커스 Cell = selectedCellColor(red), 동일 Row 다른 Cell = selectedRowColor(blue)
        let otherCol = (colIndex === 0) ? 1 : 0;
        bottom.setReturnValue("[both 선택 강조] 포커스 Cell(" + rowIndex + "," + colIndex + ")=selectedCellColor 배경색 " + getColor(rowIndex, colIndex) + " / 동일 Row 다른 Cell(" + rowIndex + "," + otherCol + ")=selectedRowColor 배경색 " + getColor(rowIndex, otherCol));
    } else {
        // 포커스 Cell 1개만 selectedCellColor(red)
        bottom.setReturnValue("[Cell 선택 강조] 포커스 Cell(" + rowIndex + "," + colIndex + ")=selectedCellColor 배경색 " + getColor(rowIndex, colIndex));
    }
}



// par_focusMode 선택값으로 setFocusMode 호출 후, 호출 전/후 focusMode 와 적용 결과 출력
//  1) 호출 직전 포커스 인덱스 캡처(beforeRow/beforeCol)
//  2) setFocusMode 호출
//  3) 호출 직후(재포커스 전) 포커스 인덱스 출력 → @spec '이전 포커스 제거'(유효 변경 시 -1) 확인
//  4) 유효 변경(cell/row/both 로 실제 변경)된 경우에만 setFocusedCell(1,1) 로 재포커스 →
//     새 focusMode 기준 선택 상태(셀/Row 강조)를 즉시 출력
//  5) 미실행(none/abc/현재값과 동일)은 '메소드 미실행' 출력 유지, 재포커스 안 함
scwin.btn_setFocusMode_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let focusMode = par_focusMode.getValue();
    let before = target1.options.focusMode;

    // 1) 호출 직전 포커스 인덱스
    let beforeRow = target1.getFocusedRowIndex();
    let beforeCol = target1.getFocusedColumnIndex();

    // 2) setFocusMode 호출
    target1.setFocusMode(focusMode);

    let after = target1.options.focusMode;

    // 3) 호출 직후(재포커스 전) 포커스 인덱스 (유효 변경 시 이전 포커스 제거되어 -1)
    let afterRow = target1.getFocusedRowIndex();
    let afterCol = target1.getFocusedColumnIndex();

    bottom.setReturnValue("[호출 focusMode] " + focusMode + " / [호출 전 focusMode] " + before + " / [호출 후 focusMode] " + after);

    // @spec: setFocusMode() 실행 시 이전 포커스 상태가 모두 제거됨 (유효 변경 시 -1)
    let removed = (afterRow === -1) ? " (이전 포커스 제거됨)" : "";
    bottom.setReturnValue("[이전 포커스 제거] 이전 포커스: row=" + beforeRow + ",col=" + beforeCol + " → 실행 직후: row=" + afterRow + ",col=" + afterCol + removed);

    if (before === after) {
        // 5) 미실행(none/abc/현재값과 동일) : focusMode 변경 없음, 재포커스 안 함
        bottom.setReturnValue("[메소드 미실행] focusMode 가 변경되지 않았습니다.");
    } else {
        // 4) 유효 변경된 경우에만 셀을 자동 선택 → 새 focusMode 의 선택 상태를 즉시 표시
        //    (setFocusMode 가 이전 포커스를 제거하므로, 새 모드의 선택 강조 확인을 위해 재포커스)
        dlt_bind.setRowPosition(1);
        target1.setFocusedCell(1, 1);
        scwin.printFocusColors(1, 1);
    }
}



// oncellclick : 사용자가 셀을 클릭하면 발생. 클릭한 셀이 포커스되며,
//  현재 focusMode 기준 선택 상태를 setFocusMode 버튼과 동일한 형식으로 출력
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();
    scwin.printFocusColors(rowIndex, columnIndex);
}
